import { expect, test } from 'bun:test';
import { AssetPack } from '../src/game/assets/asset-pack';

function fontPack() {
  const pack = new AssetPack('swf');
  Object.assign(pack, {
    fonts: new Map([
      [142, { id: 142, name: 'GoldyRound_Bold', codeTable: [65], glyphs: ['M0 0h1024v-1024h-1024Z'], advances: [20480] }],
      [741, { id: 741, name: 'GoldyRound_Regular', codeTable: [65], glyphs: ['M0 0h512v-1024h-512Z'], advances: [10240] }],
    ]),
  });
  return pack;
}

test('explicit embedded font identity takes precedence over shared name prefixes', () => {
  const pack = fontPack();
  const regular = pack.textSvg('AA', 10, '#fff', 'GoldyRound', 0, 741)!;
  expect(regular).toContain('width="10"');
  expect(regular).toContain('translate(5 10)');
  expect(regular).toContain('M0 0h512v-1024h-512Z');
  expect(regular).not.toContain('M0 0h1024v-1024h-1024Z');
  expect(pack.textSvg('AA', 10, '#fff', 'unmatched-prefix', 0, 741)).toBe(regular);
});

test('prefix selection remains the fallback for old callers and missing font IDs', () => {
  const pack = fontPack();
  const legacy = pack.textSvg('AA', 10, '#fff', 'GoldyRound')!;
  expect(legacy).toContain('width="20"');
  expect(legacy).toContain('translate(10 10)');
  expect(pack.textSvg('AA', 10, '#fff', 'GoldyRound', 0, 999)).toBe(legacy);
  expect(pack.textSvg('AA', 10, '#fff', 'missing', 0, 999)).toBeNull();
});

test('letter spacing includes known and missing glyph advances consistently', () => {
  const pack = fontPack();
  const svg = pack.textSvg('A?A', 10, '#fff', 'GoldyRound', 2, 741)!;
  expect(svg).toContain('width="20"'); // (5+2) + (4+2) + (5+2).
  expect(svg).toContain('translate(13 10)');
});

